import React, { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";
import axios from "axios";
import { Container, Card, Spinner, Alert, Button, Row, Col } from "react-bootstrap";

const UserBlogs = () => {
  const [blogs, setBlogs] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const navigate = useNavigate();
  const token = localStorage.getItem("token");
  const userId = localStorage.getItem("userId"); // Lấy userId từ localStorage

  useEffect(() => {
    if (!token || !userId) {
      setError("Bạn cần đăng nhập để xem blog của mình!");
      setLoading(false);
      return;
    }

    const fetchUserBlogs = async () => {
      try {
        const response = await axios.get(`http://localhost:9999/getuserblog/${userId}`, {
          headers: { Authorization: token },
        });

        setBlogs(response.data);
      } catch (error) {
        setError("Không thể tải blog của bạn!");
      } finally {
        setLoading(false);
      }
    };

    fetchUserBlogs();
  }, [userId, token]);

  if (loading) return <Spinner animation="border" className="d-block mx-auto mt-5" />;
  if (error) return <Alert variant="danger" className="text-center">{error}</Alert>;
  if (!blogs.length) return <Alert variant="warning" className="text-center">Bạn chưa có bài viết nào.</Alert>;

  return (
    <Container className="mt-4">
      <h2 className="text-center mb-4">Blog của bạn</h2>
      <Row>
        {blogs.map((blog) => (
          <Col md={6} lg={4} key={blog._id} className="mb-4">
            <Card className="shadow-sm">
              <Card.Img variant="top" src={blog.image} alt={blog.title} />
              <Card.Body>
                <Card.Title>{blog.title}</Card.Title>
                <Card.Text>{blog.description.substring(0, 100)}...</Card.Text>
                <Button variant="primary" onClick={() => navigate(`/blog/${blog._id}`)}>Xem chi tiết</Button>
              </Card.Body>
            </Card>
          </Col>
        ))}
      </Row>
    </Container>
  );
};

export default UserBlogs;
